// js/examples/quickloop.js
// minimal: hits local sim on http://localhost:8080/v1/generate
const fetch = require('node-fetch');
(async ()=>{
  const res = await fetch(process.env.REDWOOD_GATEWAY || 'http://localhost:8080/v1/generate',{
    method:'POST',
    headers:{'Content-Type':'application/json'},
    body: JSON.stringify({model:'rwd-small', prompt:'What is Redwood?', stream:false})
  });
  const j = await res.json();
  console.log('[SIM_RESPONSE]', j.output_text);
})();
